func TestMain(m *testing.M) {
	hermesHome, err := os.MkdirTemp("", "gormes-config-test-hermes-home-*")
	if err != nil {
		panic(err)
	}
	gormesHome, err := os.MkdirTemp("", "gormes-config-test-gormes-home-*")
	if err != nil {
		panic(err)
	}
	oldHermesHome, hadHermesHome := os.LookupEnv("HERMES_HOME")
	oldGormesHome, hadGormesHome := os.LookupEnv("GORMES_HOME")
	os.Setenv("HERMES_HOME", hermesHome)
	os.Setenv("GORMES_HOME", gormesHome)
	code := m.Run()
	if hadHermesHome {
		os.Setenv("HERMES_HOME", oldHermesHome)
	} else {
		os.Unsetenv("HERMES_HOME")
	}
	if hadGormesHome {
		os.Setenv("GORMES_HOME", oldGormesHome)
	} else {
		os.Unsetenv("GORMES_HOME")
	}
	_ = os.RemoveAll(hermesHome)
	_ = os.RemoveAll(gormesHome)
	os.Exit(code)
}

func TestLoad_BuiltinDefaults(t *testing.T) {
	t.Setenv("XDG_CONFIG_HOME", t.TempDir())
	t.Setenv("GORMES_ENDPOINT", "")
	t.Setenv("GORMES_API_KEY", "")
	cfg, err := Load(nil)
	if err != nil {
		t.Fatal(err)
	}
	if cfg.Hermes.Endpoint != "" {
		t.Errorf("default endpoint = %q, want empty so gateway does not silently dial implicit localhost", cfg.Hermes.Endpoint)
	}
	if cfg.Hermes.Model != "hermes-agent" {
		t.Errorf("default model = %q", cfg.Hermes.Model)
	}
	if cfg.Input.MaxBytes != 200_000 || cfg.Input.MaxLines != 10_000 {
		t.Errorf("default input limits = %d/%d", cfg.Input.MaxBytes, cfg.Input.MaxLines)
	}
	if cfg.TUI.MouseTracking {
		t.Error("default TUI mouse tracking = true, want false so terminal text selection works")
	}
	if cfg.CodeExecution.Mode != "strict" {
		t.Errorf("default CodeExecution.Mode = %q, want strict", cfg.CodeExecution.Mode)
	}
	if !cfg.GatewayRestartNotificationEnabled("telegram") {
		t.Error("gateway restart notification default = false, want true")
	}
	if cfg.STT.Enabled {
		t.Error("default STT.Enabled = true, want false")
	}
	if cfg.STT.Provider != "" {
		t.Errorf("default STT.Provider = %q, want empty", cfg.STT.Provider)
	}
}

func TestLoad_GatewayRestartNotificationPlatformOverride(t *testing.T) {
	cfgHome := t.TempDir()
	t.Setenv("XDG_CONFIG_HOME", cfgHome)
	t.Setenv("GORMES_HOME", filepath.Join(cfgHome, "gormes"))
	dir := filepath.Join(cfgHome, "gormes")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "config.toml"), []byte(`
[gateway.platforms.telegram]
gateway_restart_notification = false

[gateway.platforms.slack]
`), 0o644); err != nil {
		t.Fatal(err)
	}

	cfg, err := Load(nil)
	if err != nil {
		t.Fatal(err)
	}
	if cfg.GatewayRestartNotificationEnabled("telegram") {
		t.Fatal("telegram gateway restart notification = true, want false from native TOML override")
	}
	if !cfg.GatewayRestartNotificationEnabled("slack") {
		t.Fatal("slack gateway restart notification = false, want default true when platform section omits flag")
	}
	if !cfg.GatewayRestartNotificationEnabled("discord") {
		t.Fatal("discord gateway restart notification = false, want default true with no platform section")
	}
}

